VANHOUTEN LIVING — FINAL PRODUCT HERO
Clean stable version
============================================================
{% endcomment %}

<style>

/* =========================================================
   01. BASIS
========================================================= */

.shop-product-section {
  --vhl-text: #50504f;
  --vhl-muted: #747471;
  --vhl-border: #dededb;
  --vhl-soft: #f7f7f5;
  --vhl-button: #535351;
  --vhl-button-hover: #40403f;

  background: #ffffff !important;
  color: var(--vhl-text) !important;

  min-height: 0 !important;
  height: auto !important;

  padding-top: 34px !important;
  padding-bottom: 56px !important;
}

.shop-product-section *,
.shop-product-section *::before,
.shop-product-section *::after {
  box-sizing: border-box;
}


/* =========================================================
   02. DESKTOP HOOFDLAYOUT
========================================================= */

@media screen and (min-width: 990px) {

  .shop-product-section .shop-product-inner-container {
    width: min(100% - 64px, 1500px) !important;
    max-width: 1500px !important;

    margin: 0 auto !important;
    padding: 0 !important;
  }

  .shop-product-section .shop-product-layout {
    display: grid !important;

    /*
      Fotografie krijgt het grootste deel.
      Buy box blijft premium 540px.
    */
    grid-template-columns:
      minmax(0, 1fr)
      540px !important;

    column-gap: 64px !important;

    align-items: start !important;

    width: 100% !important;

    height: auto !important;
    min-height: 0 !important;
  }

  .shop-product-section .shop-product-info {
    width: 540px !important;
    min-width: 540px !important;
    max-width: 540px !important;

    margin: 0 !important;
    padding: 0 !important;

    align-self: start !important;

    height: auto !important;
    min-height: 0 !important;
  }
}


/* =========================================================
   03. PRODUCT GALLERY
   Geen JS-layout hacks.
========================================================= */

.shop-product-section .shop-carousel-container {
  width: 100% !important;
  max-width: none !important;
  min-width: 0 !important;

  margin: 0 !important;
  padding: 0 !important;

  height: auto !important;
  min-height: 0 !important;
}


@media screen and (min-width: 990px) {

  .shop-product-section .shop-carousel-container {
    display: flex !important;

    flex-direction: row !important;
    align-items: flex-start !important;

    gap: 14px !important;

    overflow: visible !important;
  }


  /* -------------------------
     THUMBNAILS
  ------------------------- */

  .shop-product-section .shop-thumbnails-outer {
    flex: 0 0 74px !important;

    width: 74px !important;
    min-width: 74px !important;
    max-width: 74px !important;

    margin: 0 !important;
    padding: 0 !important;
  }

  .shop-product-section .shop-thumbnails-wrapper {
    display: flex !important;
    flex-direction: column !important;

    width: 74px !important;

    gap: 9px !important;

    margin: 0 !important;
    padding: 0 !important;
  }

  .shop-product-section .shop-thumbnail {
    display: block !important;

    flex: 0 0 74px !important;

    width: 74px !important;
    height: 74px !important;

    margin: 0 !important;
    padding: 0 !important;

    background: var(--vhl-soft) !important;

    border: 1px solid transparent !important;
    border-radius: 0 !important;

    overflow: hidden !important;

    box-shadow: none !important;
  }

  .shop-product-section .shop-thumbnail.active,
  .shop-product-section .shop-thumbnail[aria-current="true"] {
    border-color: #50504f !important;
  }

  .shop-product-section .shop-thumbnail img {
    display: block !important;

    width: 100% !important;
    height: 100% !important;

    object-fit: cover !important;
    object-position: center !important;
  }


  /* -------------------------
     HOOFDAFBEELDING
  ------------------------- */

  .shop-product-section .shop-main-image-wrapper {
    flex: 1 1 0 !important;

    width: auto !important;
    min-width: 0 !important;
    max-width: none !important;

    margin: 0 !important;
    padding: 0 !important;
  }

  .shop-product-section .shop-image-container,
  .shop-product-section .shop-square-container {
    display: block !important;

    width: 100% !important;

    aspect-ratio: 1 / 1 !important;

    height: auto !important;
    min-height: 0 !important;
    max-height: none !important;

    margin: 0 !important;
    padding: 0 !important;

    background: var(--vhl-soft) !important;

    border-radius: 0 !important;

    overflow: hidden !important;
  }

  .shop-product-section .shop-main-image,
  .shop-product-section .shop-main-image-wrapper img,
  .shop-product-section .shop-image-container img,
  .shop-product-section .shop-square-container img {
    display: block !important;

    width: 100% !important;
    height: 100% !important;

    max-width: none !important;
    max-height: none !important;

    object-fit: cover !important;
    object-position: center !important;

    border-radius: 0 !important;
  }
}


/* =========================================================
   04. TITEL
========================================================= */

.shop-product-section .shop-product-title,
.shop-product-section [class*="product-title"] h1,
.shop-product-section h1 {
  margin: 0 0 22px !important;

  color: var(--vhl-text) !important;

  font-size: 31px !important;
  font-weight: 400 !important;

  line-height: 1.14 !important;
  letter-spacing: -0.025em !important;

  text-transform: none !important;
}


/* =========================================================
   05. PRIJS
========================================================= */

.shop-product-section .shop-product-price {
  display: block !important;

  width: 100% !important;

  margin: 0 !important;
  padding: 0 0 23px !important;

  color: var(--vhl-text) !important;

  font-size: 20px !important;
  font-weight: 400 !important;

  line-height: 1.2 !important;

  border-bottom: 1px solid var(--vhl-border) !important;
}

.shop-product-section [class*="save-badge"],
.shop-product-section [class*="sale-badge"] {
  display: none !important;
}


/* =========================================================
   06. VARIANTEN
========================================================= */

.shop-product-section .simple-variant-picker {
  width: 100% !important;

  margin: 27px 0 0 !important;
}

.shop-product-section .simple-variant-picker__option {
  margin: 0 0 21px !important;
}

.shop-product-section .simple-variant-picker__label-header {
  display: flex !important;

  align-items: baseline !important;

  gap: 5px !important;

  margin: 0 0 10px !important;

  color: var(--vhl-text) !important;

  font-size: 13px !important;
  font-weight: 400 !important;

  line-height: 1.3 !important;

  letter-spacing: 0 !important;

  text-transform: none !important;
}

.shop-product-section .simple-variant-picker__label-header strong,
.shop-product-section .simple-variant-picker__label-header b {
  font-weight: 500 !important;
}

.shop-product-section .simple-variant-picker__values {
  display: flex !important;

  flex-wrap: wrap !important;

  gap: 10px !important;
}


/* =========================================================
   07. VARIANT PILLS
========================================================= */

.shop-product-section .simple-variant-picker__value {
  appearance: none !important;
  -webkit-appearance: none !important;

  display: inline-flex !important;

  align-items: center !important;
  justify-content: center !important;

  min-width: 0 !important;
  min-height: 42px !important;

  margin: 0 !important;

  padding: 10px 17px !important;

  background: #ffffff !important;

  color: var(--vhl-text) !important;

  border: 1px solid #d7d7d4 !important;
  border-radius: 999px !important;

  box-shadow: none !important;

  font-family: inherit !important;

  font-size: 13px !important;
  font-weight: 400 !important;

  line-height: 1 !important;

  text-transform: none !important;

  transition:
    background-color .16s ease,
    border-color .16s ease,
    color .16s ease !important;
}

.shop-product-section .simple-variant-picker__value:hover {
  border-color: #858582 !important;
}

.shop-product-section input[type="radio"]:checked + label,
.shop-product-section .simple-variant-picker__value[aria-pressed="true"],
.shop-product-section .simple-variant-picker__value.is-selected,
.shop-product-section .simple-variant-picker__value.selected {
  background: var(--vhl-text) !important;

  color: #ffffff !important;

  border-color: var(--vhl-text) !important;
}


/* =========================================================
   08. KLEUR SWATCH
========================================================= */

.shop-product-section
.vhl-color-option
.simple-variant-picker__value {
  position: relative !important;

  width: 38px !important;
  min-width: 38px !important;

  height: 38px !important;
  min-height: 38px !important;

  padding: 4px !important;

  background: #ffffff !important;

  border: 1px solid #c9c9c6 !important;
  border-radius: 50% !important;

  font-size: 0 !important;

  overflow: hidden !important;
}

.shop-product-section
.vhl-color-option
.simple-variant-picker__value::after {
  content: "";

  display: block;

  width: 100%;
  height: 100%;

  background: var(--vhl-swatch, #b8b2ab);

  border-radius: 50%;
}

.shop-product-section
.vhl-color-option
input[type="radio"]:checked + label {
  background: #ffffff !important;

  border-color: var(--vhl-text) !important;

  box-shadow: 0 0 0 1px var(--vhl-text) !important;
}


/* Technische optie met slechts één keuze niet tonen */

.shop-product-section .vhl-hide-single-option {
  display: none !important;
}


/* =========================================================
   09. BUY ROW
========================================================= */

.shop-product-section .vhl-buy-row {
  display: grid !important;

  grid-template-columns:
    150px
    minmax(0, 1fr) !important;

  gap: 14px !important;

  align-items: stretch !important;

  width: 100% !important;

  margin: 28px 0 0 !important;
}


/* =========================================================
   10. QUANTITY
========================================================= */

.shop-product-section .vhl-quantity {
  display: grid !important;

  grid-template-columns:
    49px 52px 49px !important;

  width: 150px !important;
  height: 52px !important;

  margin: 0 !important;
  padding: 0 !important;

  background: #ffffff !important;

  border: 1px solid var(--vhl-border) !important;
  border-radius: 999px !important;

  overflow: hidden !important;

  box-shadow: none !important;
}

.shop-product-section .vhl-qty-btn,
.shop-product-section .vhl-qty-value {
  appearance: none !important;
  -webkit-appearance: none !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  width: 100% !important;
  height: 50px !important;

  margin: 0 !important;
  padding: 0 !important;

  background: transparent !important;

  color: var(--vhl-text) !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-family: inherit !important;

  line-height: 1 !important;
}

.shop-product-section .vhl-qty-btn {
  font-size: 18px !important;
  font-weight: 300 !important;

  cursor: pointer !important;
}

.shop-product-section .vhl-qty-value {
  font-size: 14px !important;
  font-weight: 400 !important;

  border-left: 1px solid #e7e7e4 !important;
  border-right: 1px solid #e7e7e4 !important;
}

.shop-product-section .vhl-qty-btn:hover {
  background: #f7f7f5 !important;
}


/* =========================================================
   11. ADD TO CART
========================================================= */

.shop-product-section
.vhl-buy-row
.product-form__submit,

.shop-product-section
.vhl-buy-row
button[name="add"] {
  appearance: none !important;
  -webkit-appearance: none !important;

  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  width: 100% !important;

  height: 52px !important;
  min-height: 52px !important;

  margin: 0 !important;

  padding: 0 24px !important;

  background: var(--vhl-button) !important;

  color: #ffffff !important;

  border: 1px solid var(--vhl-button) !important;
  border-radius: 999px !important;

  box-shadow: none !important;

  font-size: 12px !important;
  font-weight: 500 !important;

  line-height: 1.1 !important;

  letter-spacing: .02em !important;

  text-align: center !important;

  text-transform: uppercase !important;

  transition:
    background-color .18s ease,
    border-color .18s ease !important;
}

.shop-product-section
.vhl-buy-row
.product-form__submit:hover,

.shop-product-section
.vhl-buy-row
button[name="add"]:hover {
  background: var(--vhl-button-hover) !important;

  border-color: var(--vhl-button-hover) !important;
}


/* =========================================================
   12. TRUST BLOKKEN
========================================================= */

.shop-product-section .vhl-service-stack {
  display: grid !important;

  width: 100% !important;

  gap: 8px !important;

  margin: 17px 0 0 !important;
}

.shop-product-section .vhl-service-item {
  display: grid !important;

  grid-template-columns:
    38px
    minmax(0, 1fr) !important;

  align-items: center !important;

  gap: 13px !important;

  min-height: 60px !important;

  padding: 11px 16px !important;

  background: var(--vhl-soft) !important;

  border: 0 !important;
  border-radius: 0 !important;
}

.shop-product-section .vhl-service-icon {
  display: flex !important;

  align-items: center !important;
  justify-content: center !important;

  width: 28px !important;
  height: 28px !important;
}

.shop-product-section .vhl-service-icon svg {
  display: block !important;

  width: 23px !important;
  height: 23px !important;

  fill: none !important;

  stroke: #686865 !important;
  stroke-width: 1.4 !important;
}

.shop-product-section .vhl-service-title {
  margin: 0 0 2px !important;

  color: var(--vhl-text) !important;

  font-size: 12.5px !important;
  font-weight: 600 !important;

  line-height: 1.3 !important;
}

.shop-product-section .vhl-service-text {
  margin: 0 !important;

  color: var(--vhl-muted) !important;

  font-size: 11.5px !important;
  font-weight: 400 !important;

  line-height: 1.4 !important;
}


/* =========================================================
   13. ACCORDIONS
========================================================= */

.shop-product-section .vhl-accordions {
  width: 100% !important;

  margin: 25px 0 0 !important;

  border-top: 1px solid var(--vhl-border) !important;
}

.shop-product-section .vhl-accordion {
  border-bottom: 1px solid var(--vhl-border) !important;
}

.shop-product-section .vhl-accordion-button {
  appearance: none !important;
  -webkit-appearance: none !important;

  display: flex !important;

  align-items: center !important;
  justify-content: space-between !important;

  width: 100% !important;

  min-height: 57px !important;

  margin: 0 !important;
  padding: 0 !important;

  background: transparent !important;

  color: var(--vhl-text) !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-family: inherit !important;

  font-size: 14px !important;
  font-weight: 400 !important;

  line-height: 1.3 !important;

  text-align: left !important;

  cursor: pointer !important;
}

.shop-product-section .vhl-accordion-icon {
  position: relative !important;

  display: block !important;

  width: 18px !important;
  height: 18px !important;

  flex: 0 0 18px !important;

  margin-left: 20px !important;
}

.shop-product-section .vhl-accordion-icon::before,
.shop-product-section .vhl-accordion-icon::after {
  content: "";

  position: absolute;

  top: 50%;
  left: 50%;

  width: 14px;
  height: 1px;

  background: var(--vhl-text);

  transform: translate(-50%, -50%);
}

.shop-product-section .vhl-accordion-icon::after {
  transform:
    translate(-50%, -50%)
    rotate(90deg);

  transition: transform .18s ease;
}

.shop-product-section
.vhl-accordion.is-open
.vhl-accordion-icon::after {
  transform:
    translate(-50%, -50%)
    rotate(0deg);
}

.shop-product-section .vhl-accordion-content {
  display: none !important;

  padding: 0 0 24px !important;

  color: #696966 !important;

  font-size: 13px !important;
  font-weight: 400 !important;

  line-height: 1.65 !important;
}

.shop-product-section
.vhl-accordion.is-open
.vhl-accordion-content {
  display: block !important;
}

.shop-product-section .vhl-accordion-content p {
  margin: 0 0 12px !important;
}

.shop-product-section .vhl-accordion-content p:last-child {
  margin-bottom: 0 !important;
}


/* =========================================================
   14. BETALING / THEME NOISE
========================================================= */

/*
   Laat theme-native betalingsblokken met rust.
   Alleen extra tekstschaduwen verwijderen.
*/

.shop-product-section *,
.shop-product-section button,
.shop-product-section label {
  text-shadow: none !important;
}


/* =========================================================
   15. TABLET
========================================================= */

@media screen and (min-width: 750px) and (max-width: 989px) {

  .shop-product-section {
    padding-top: 24px !important;
    padding-bottom: 42px !important;
  }

  .shop-product-section .shop-product-layout {
    display: block !important;

    width: min(100% - 48px, 880px) !important;

    margin: 0 auto !important;
  }

  .shop-product-section .shop-product-info {
    width: 100% !important;

    min-width: 0 !important;
    max-width: none !important;

    margin-top: 34px !important;

    padding: 0 !important;
  }
}


/* =========================================================
   16. MOBIEL
========================================================= */

@media screen and (max-width: 749px) {

  .shop-product-section {
    padding-top: 0 !important;
    padding-bottom: 34px !important;
  }

  .shop-product-section .shop-product-layout {
    display: block !important;

    width: 100% !important;

    margin: 0 !important;
    padding: 0 !important;
  }

  /*
    Gallery op mobiel blijft native Shopify/theme.
    Geen desktop flex/grid afdwingen.
  */

  .shop-product-section .shop-carousel-container {
    display: block !important;

    width: 100% !important;

    margin: 0 !important;
  }

  .shop-product-section .shop-product-info {
    width: 100% !important;

    min-width: 0 !important;
    max-width: none !important;

    margin: 0 !important;

    padding:
      27px
      20px
      0 !important;
  }

  .shop-product-section .shop-product-title,
  .shop-product-section h1 {
    margin-bottom: 18px !important;

    font-size: 27px !important;

    line-height: 1.16 !important;
  }

  .shop-product-section .shop-product-price {
    font-size: 18px !important;

    padding-bottom: 20px !important;
  }

  .shop-product-section .simple-variant-picker {
    margin-top: 23px !important;
  }

  .shop-product-section .vhl-buy-row {
    grid-template-columns:
      116px
      minmax(0, 1fr) !important;

    gap: 10px !important;

    margin-top: 23px !important;
  }

  .shop-product-section .vhl-quantity {
    grid-template-columns:
      38px 40px 38px !important;

    width: 116px !important;

    height: 50px !important;
  }

  .shop-product-section .vhl-qty-btn,
  .shop-product-section .vhl-qty-value {
    height: 48px !important;
  }

  .shop-product-section
  .vhl-buy-row
  .product-form__submit,

  .shop-product-section
  .vhl-buy-row
  button[name="add"] {
    height: 50px !important;
    min-height: 50px !important;

    padding: 0 12px !important;

    font-size: 10.5px !important;
  }

  .shop-product-section .vhl-service-item {
    min-height: 57px !important;

    padding: 10px 13px !important;
  }

  .shop-product-section .vhl-accordions {
    margin-top: 22px !important;
  }
}

</style>


<script>
(function () {

  const COLOR_MAP = {
    bruin: '#76543c',
    brown: '#76543c',

    beige: '#d6cabc',
    stone: '#d9d5cf',

    zwart: '#222222',
    black: '#222222',

    wit: '#f5f5f3',
    white: '#f5f5f3',

    grijs: '#8c8c89',
    grey: '#8c8c89',
    gray: '#8c8c89',

    groen: '#687364',
    green: '#687364',

    blauw: '#65717c',
    blue: '#65717c'
  };


  function getProductSection() {

    return (
      document.querySelector('.shop-product-section') ||
      document.querySelector('[class*="product-details"]')
    );

  }


  /* ======================================================
     VARIANT PICKER
  ====================================================== */

  function setupVariants() {

    const section = getProductSection();

    if (!section) return;


    section
      .querySelectorAll('.simple-variant-picker__option')
      .forEach(function (option) {

        const text =
          option.textContent
            .trim()
            .toLowerCase();


        const radios =
          option.querySelectorAll(
            'input[type="radio"]'
          );


        const labels =
          option.querySelectorAll(
            '.simple-variant-picker__value'
          );


        /*
          Kleur herkennen.
        */

        if (
          text.includes('kleur') ||
          text.includes('color') ||
          text.includes('colour')
        ) {

          option.classList.add(
            'vhl-color-option'
          );


          labels.forEach(function (label) {

            const value =
              label.textContent
                .trim()
                .toLowerCase();


            label.style.setProperty(
              '--vhl-swatch',
              COLOR_MAP[value] || '#b8b2ab'
            );

          });


          return;

        }


        /*
          Een technische variantoptie met maar
          één mogelijke keuze heeft geen UX-waarde.
        */

        if (radios.length === 1) {

          option.classList.add(
            'vhl-hide-single-option'
          );

        }

      });

  }


  /* ======================================================
     QUANTITY + ADD TO CART
  ====================================================== */

  function createBuyRow() {

    const section = getProductSection();

    if (!section) return;


    if (
      section.querySelector('.vhl-buy-row')
    ) {
      return;
    }


    const addButton =
      section.querySelector(
        '.product-form__submit'
      ) ||
      section.querySelector(
        'button[name="add"]'
      );


    if (!addButton) return;


    const form =
      addButton.closest('form');


    if (!form) return;


    let quantityInput =
      form.querySelector(
        'input[name="quantity"]'
      );


    if (!quantityInput) {

      quantityInput =
        document.createElement('input');

      quantityInput.type = 'hidden';

      quantityInput.name = 'quantity';

      quantityInput.value = '1';

      form.appendChild(
        quantityInput
      );

    }


    const row =
      document.createElement('div');

    row.className =
      'vhl-buy-row';


    const quantity =
      document.createElement('div');

    quantity.className =
      'vhl-quantity';


    quantity.innerHTML = `
      <button
        type="button"
        class="vhl-qty-btn vhl-minus"
        aria-label="Aantal verlagen"
      >−</button>

      <span
        class="vhl-qty-value"
        aria-live="polite"
      >1</span>

      <button
        type="button"
        class="vhl-qty-btn vhl-plus"
        aria-label="Aantal verhogen"
      >+</button>
    `;


    addButton.parentNode.insertBefore(
      row,
      addButton
    );


    row.appendChild(
      quantity
    );


    row.appendChild(
      addButton
    );


    const minus =
      quantity.querySelector('.vhl-minus');

    const plus =
      quantity.querySelector('.vhl-plus');

    const display =
      quantity.querySelector('.vhl-qty-value');


    function getQuantity() {

      const value =
        parseInt(
          quantityInput.value,
          10
        );


      return Number.isNaN(value)
        ? 1
        : Math.max(1, value);

    }


    function setQuantity(value) {

      const next =
        Math.max(
          1,
          parseInt(value, 10) || 1
        );


      quantityInput.value =
        next;


      display.textContent =
        next;


      quantityInput.dispatchEvent(
        new Event('input', {
          bubbles: true
        })
      );


      quantityInput.dispatchEvent(
        new Event('change', {
          bubbles: true
        })
      );

    }


    minus.addEventListener(
      'click',
      function () {

        setQuantity(
          getQuantity() - 1
        );

      }
    );


    plus.addEventListener(
      'click',
      function () {

        setQuantity(
          getQuantity() + 1
        );

      }
    );


    setQuantity(
      getQuantity()
    );

  }


  /* ======================================================
     TRUST BLOKKEN
  ====================================================== */

  function createServices() {

    const section =
      getProductSection();


    if (!section) return;


    if (
      section.querySelector(
        '.vhl-service-stack'
      )
    ) {
      return;
    }


    const buyRow =
      section.querySelector(
        '.vhl-buy-row'
