          <p class="vhl-service-title">
            Met zorg geselecteerd
          </p>

          <p class="vhl-service-text">
            Gekozen op uitstraling, functionaliteit en afwerking.
          </p>

        </div>

      </div>

    `;


    buyRow.insertAdjacentElement(
      'afterend',
      services
    );

  }


  /* ======================================================
     ACCORDIONS
  ====================================================== */

  const vhlDetailsHtml =
    {{ product.metafields.custom.details | metafield_tag | json }};

  const vhlSpecificationsHtml =
    {{ product.metafields.custom.specifications | metafield_tag | json }};

  function createAccordions() {

    const section =
      getProductSection();


    if (!section) return;


    if (
      section.querySelector(
        '.vhl-accordions'
      )
    ) {
      return;
    }


    const services =
      section.querySelector(
        '.vhl-service-stack'
      );


    if (!services) return;


    const accordions =
      document.createElement('div');


    accordions.className =
      'vhl-accordions';


    accordions.innerHTML = `

      <div class="vhl-accordion is-open">

        <button
          type="button"
          class="vhl-accordion-button"
          aria-expanded="true"
        >
          <span>Details</span>
          <span class="vhl-accordion-icon"></span>
        </button>


        <div class="vhl-accordion-content">

          ${vhlDetailsHtml || `
            <p>
              Voeg bij dit product inhoud toe via het metafield Details.
            </p>
          `}

        </div>

      </div>


      <div class="vhl-accordion">

        <button
          type="button"
          class="vhl-accordion-button"
          aria-expanded="false"
        >
          <span>Specificaties</span>
          <span class="vhl-accordion-icon"></span>
        </button>


        <div class="vhl-accordion-content">

          ${vhlSpecificationsHtml || `
            <p>
              Voeg bij dit product inhoud toe via het metafield Specificaties.
            </p>
          `}

        </div>

      </div>


      <div class="vhl-accordion">

        <button
          type="button"
          class="vhl-accordion-button"
          aria-expanded="false"
        >
          <span>Verzending & retourneren</span>
          <span class="vhl-accordion-icon"></span>
        </button>


        <div class="vhl-accordion-content">

          <p>
            Gratis verzending vanaf €50.
          </p>

          <p>
            Je bestelling wordt zorgvuldig verpakt
            en naar het gekozen afleveradres verzonden.
          </p>

        </div>

      </div>

    `;


    services.insertAdjacentElement(
      'afterend',
      accordions
    );


    accordions
      .querySelectorAll(
        '.vhl-accordion-button'
      )
      .forEach(function (button) {

        button.addEventListener(
          'click',
          function () {

            const accordion =
              button.closest(
                '.vhl-accordion'
              );


            const open =
              accordion.classList.contains(
                'is-open'
              );


            accordion.classList.toggle(
              'is-open',
              !open
            );


            button.setAttribute(
              'aria-expanded',
              String(!open)
            );

          }
        );

      });

  }


  /* ======================================================
     INITIALISATIE
  ====================================================== */

  function initVHLProduct() {

    setupVariants();

    createBuyRow();

    createServices();

    createAccordions();

  }


  if (
    document.readyState === 'loading'
  ) {

    document.addEventListener(
      'DOMContentLoaded',
      initVHLProduct
    );

  } else {

    initVHLProduct();

  }


  /*
    Alleen nodig voor Shopify Theme Editor.
  */

  document.addEventListener(
    'shopify:section:load',
    function () {

      setTimeout(
        initVHLProduct,
        120
      );

    }
  );


  /*
    Kleine fallback wanneer het productcomponent
    iets later rendert.
  */

  setTimeout(
    initVHLProduct,
    400
  );

})();
</script>

